from datetime import date, timedelta
import calendar


_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    k = int(parts[1])
    result = []

    def add(d):
        if d >= s and len(result) < count:
            result.append(d.isoformat())

    if kind == "DAILY":
        j = 0
        while len(result) < count:
            add(s + timedelta(days=k * j))
            j += 1

    elif kind == "WEEKLY":
        days = sorted({_WEEKDAYS[c] for c in parts[2].split(",")})
        monday = s - timedelta(days=s.weekday())
        w = 0
        while len(result) < count:
            for wd in days:
                add(monday + timedelta(days=7 * k * w + wd))
            w += 1

    elif kind == "MONTHLY":
        base = s.year * 12 + s.month - 1
        j = 0
        while len(result) < count:
            y, m0 = divmod(base + j * k, 12)
            m = m0 + 1
            dim = calendar.monthrange(y, m)[1]
            if len(parts) == 3:
                spec = int(parts[2])
                day = dim if spec == -1 else spec
                if 1 <= day <= dim:
                    add(date(y, m, day))
            else:
                n = int(parts[2])
                wd = _WEEKDAYS[parts[3]]
                if n > 0:
                    first = date(y, m, 1)
                    day = 1 + (wd - first.weekday()) % 7 + 7 * (n - 1)
                else:
                    last = date(y, m, dim)
                    day = dim - (last.weekday() - wd) % 7
                if 1 <= day <= dim:
                    add(date(y, m, day))
            j += 1

    elif kind == "YEARLY":
        mm, dd = map(int, parts[2].split("-"))
        j = 0
        while len(result) < count:
            try:
                add(date(s.year + j * k, mm, dd))
            except ValueError:
                pass
            j += 1

    return result
